def criar_movimentos_de_expedicao(apps, schema_editor):
    AutorizacaoMovimento = apps.get_model("sistema", "AutorizacaoMovimento")
    AutorizacaoAmbiental = apps.get_model("sistema", "AutorizacaoAmbiental")
    Expedicao = apps.get_model("sistema", "Expedicao")
    banco = schema_editor.connection.alias

    for expedicao in Expedicao.objects.using(banco).iterator():
        autorizacao = AutorizacaoAmbiental.objects.using(banco).get(
            pk=expedicao.autorizacao_id
        )
        volume = (
            expedicao.volume_expedido
            if expedicao.volume_aferido is None
            else expedicao.volume_aferido
        )
        AutorizacaoMovimento.objects.using(banco).create(
            empresa_id=expedicao.empresa_id,
            autorizacao_id=expedicao.autorizacao_id,
            tipo_movimento="EXPEDICAO_CARVAO",
            data_movimento=expedicao.data_expedicao,
            expedicao_id=expedicao.pk,
            volume_original=expedicao.volume_expedido,
            unidade_original=autorizacao.unidade_volume,
            volume_movimentado=volume,
            usuario_inclusao_id=expedicao.usuario_inclusao_id,
            usuario_alteracao_id=expedicao.usuario_alteracao_id,
        )


